local Reverse = {}
for english, russian in pairs(Dictionary) do
  if type(russian) == "string" and russian ~= "" then Reverse[russian] = english end
end
local function Translation(text)
  if type(text) ~= "string" or text == "" then return text end
  local exact = Dictionary[text]
  if exact then return exact end
  local _, _, leading, body, trailing = string.find(text, "^(%s*)(.-)(%s*)$")
  if body and Dictionary[body] then return leading .. Dictionary[body] .. trailing end
  local _, _, count, branch = string.find(text, "^Requires (%d+) points in (.-)%.$")
  if count then return "Требуется " .. count .. " очков в ветке «" .. (Dictionary[branch] or branch) .. "»." end
  return text
end
HordesRU_FullTranslate = Translation
HordesRU_FullDictionary = Dictionary
HordesRU_FullMastery = Mastery
local function StoreMissing(category, id, original)
  if type(original) ~= "string" or not string.find(original, "[A-Za-z]") then return end
  HordesRU_LiveMissing = HordesRU_LiveMissing or {}
  local key = tostring(category) .. ":" .. tostring(id or "?")
  if not HordesRU_LiveMissing[key] then HordesRU_LiveMissing[key] = original end
end
local function LocalizeNode(node)
  if type(node) ~= "table" then return end
  local id = tonumber(node.id)
  local item = id and Mastery[id]
  local oldName = node._HordesRU_EnglishName or node.name
  local oldDescription = node._HordesRU_EnglishDescription or node.description
  if type(oldName) == "string" then
    local newName = Dictionary[oldName]
    if not newName and item and (oldName == item[1] or node.name == item[2]) then newName=item[2] end
    if newName and newName ~= "" then node.name=newName end
  end
  if type(oldDescription) == "string" then
    local translated = Dictionary[oldDescription]
    if not translated and item and (oldDescription == item[3] or node.description == item[4]) then translated=item[4] end
    if translated and translated ~= "" then
      node._HordesRU_EnglishDescription = oldDescription
      node.description = translated
      Reverse[translated] = oldDescription
    else
      StoreMissing("mastery",id,oldDescription)
    end
  end
  if type(node.pair) == "table" then
    for _, choice in ipairs(node.pair) do if choice ~= node then LocalizeNode(choice) end end
  end
end
local hookedTalent,hookedTip,hookedSpell,hookedOffer,hookedGlossary=false,false,false,false,false
local function IsHordesOwner(widget)
  if not widget or type(widget.GetOwner) ~= "function" then return false end
  local owner=widget:GetOwner()
  local limit=0
  while owner and limit < 20 do
    if owner.node or owner.pair then return true end
    if type(owner.GetName) == "function" then
      local ok, name=pcall(owner.GetName,owner)
      if ok and type(name)=="string" and string.find(name,"VanillaBonk",1,true) then return true end
    end
    if type(owner.GetParent) ~= "function" then break end
    owner=owner:GetParent()
    limit=limit+1
  end
  return false
end
local function HookTalent()
  local t=VanillaBonkTalents
  if hookedTalent or type(t)~="table" or type(t.ParseNode)~="function" then return end
  hookedTalent=true
  local oldParse=t.ParseNode
  t.ParseNode=function(node, fields)
    local result=oldParse(node,fields)
    LocalizeNode(node)
    return result
  end
  if type(t.Show)=="function" then
    local oldShow=t.Show
    t.Show=function(shop, data, top)
      if type(data)=="table" then
        if type(data.nodes)=="table" then
          for _, n in pairs(data.nodes) do LocalizeNode(n) end
        end
      end
      return oldShow(shop,data,top)
    end
  end
end
local function HookGlossary()
  if hookedGlossary or type(VanillaBonkUI)~="table" or type(VanillaBonkUI.AddGlossary)~="function" then return end
  hookedGlossary=true
  local old=VanillaBonkUI.AddGlossary
  VanillaBonkUI.AddGlossary=function(tooltip, descriptions)
    if type(descriptions)~="table" then return old(tooltip,descriptions) end
    local originals={}
    for index, value in ipairs(descriptions) do
      originals[index]=Reverse[value] or value
    end
    return old(tooltip,originals)
  end
end
local function HookTooltip()
  if hookedTip or not GameTooltip or type(GameTooltip.AddLine)~="function" then return end
  hookedTip=true
  local old=GameTooltip.AddLine
  GameTooltip.AddLine=function(self, text, r,g,b,wrap)
    if type(text)=="string" and (IsHordesOwner(self) or Dictionary[text]) then
      local translated=Translation(text)
      if translated~=text then
        text=translated
        wrap=1
      end
    end
    return old(self,text,r,g,b,wrap)
  end
end
local function HookSpell()
  local t=VanillaBonkSpellTip
  if hookedSpell or type(t)~="table" or type(t.AddLine)~="function" then return end
  hookedSpell=true
  local old=t.AddLine
  t.AddLine=function(self,text,r,g,b) return old(self,Translation(text),r,g,b) end
  if type(t.Title)=="function" then
    local oldTitle=t.Title
    t.Title=function(self,text,color,tags)
      return oldTitle(self,Translation(text),color,tags)
    end
  end
end
local function HookOffer()
  local offer=VanillaBonkOffer
  if hookedOffer or type(offer)~="table" or type(offer.FitCard)~="function" then return end
  hookedOffer=true
  local old=offer.FitCard
  offer.FitCard=function(card,option,width,hasLock)
    if type(option)~="table" then return old(card,option,width,hasLock) end
    local name=Translation(option.name)
    local description=Translation(option.description)
    if name~=option.name or description~=option.description then
      local copy={}
      for k,v in pairs(option) do copy[k]=v end
      copy.name=name
      copy.description=description
      return old(card,copy,width,hasLock)
    end
    return old(card,option,width,hasLock)
  end
end
local function Setup()
  HookTalent()
  HookGlossary()
  HookTooltip()
  HookSpell()
  HookOffer()
end
local installed=CreateFrame("Frame")
local nextTry=0
installed:SetScript("OnUpdate",function()
  if GetTime() < nextTry then return end
  nextTry=GetTime()+2
  Setup()
end)
Setup()
